'use strict';
// Nightly. For each agent who owns tickets rated in the past seven days, writes how many ratings there were and their
// average score. The agent is the ticket's owner at run time. Agents with no ratings in the window get no row.

const WINDOW_DAYS = 7;
const DAY = 24 * 60 * 60 * 1000;

function summariseRatings(store, { now = new Date() } = {}) {
  const since = now.getTime() - WINDOW_DAYS * DAY;
  const weekEnding = now.toISOString().slice(0, 10);
  const byAgent = new Map();
  for (const t of store.listTickets()) {
    if (t.rating_score == null || !t.owner_id) continue;
    if (new Date(t.rated_at).getTime() < since) continue;
    const acc = byAgent.get(t.owner_id) || { sum: 0, count: 0 };
    acc.sum += t.rating_score;
    acc.count += 1;
    byAgent.set(t.owner_id, acc);
  }
  const rows = [...byAgent].sort(([a], [b]) => a - b).map(([agentId, { sum, count }]) => ({
    agent_id: agentId,
    week_ending: weekEnding,
    rating_count: count,
    average_score: Math.round((sum / count) * 100) / 100,
  }));
  for (const row of rows) store.upsertAgentSummary(row);
  return rows;
}

module.exports = { summariseRatings, WINDOW_DAYS };
```

